def ru_piece_join(s):
    if s.strip() in PIECES:
        return PIECES[s.strip()]
    parts = [p.strip() for p in s.split("•")]
    out = []
    for p in parts:
        if p in PIECES:
            out.append(PIECES[p])
        else:
            out.append(p)
    return " • ".join(out)
